#### Example 1: Tenant Context Middleware (C#)

```csharp
public class TenantContextMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ITenantIdentifierService _tenantService;

    public TenantContextMiddleware(RequestDelegate next, ITenantIdentifierService tenantService)
    {
        _next = next;
        _tenantService = tenantService;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var tenantId = ExtractTenantId(context.Request);
        var tenantInfo = await _tenantService.GetTenantAsync(tenantId);

        if (tenantInfo == null)
            throw new TenantNotFoundException(tenantId);

        using (TenantContext.BeginScope(tenantInfo))
        {
            await _next(context);
        }
    }

    private string ExtractTenantId(HttpRequest request)
    {
        // Try subdomain first
        var host = request.Host.Host;
        var parts = host.Split('.');
        if (parts.Length > 2) return parts[0];

        // Try header
        if (request.Headers.TryGetValue("X-Tenant-ID", out var headerValue))
            return headerValue;

        throw new TenantIdentificationException("Unable to identify tenant");
    }
}
```

