#### Example 2: Tenant-Aware Service Base Class

```csharp
public abstract class TenantAwareService
{
    protected string TenantId => TenantContext.Current.TenantId;
    protected TenantInfo Tenant => TenantContext.Current;

    protected IDbConnection GetConnection()
    {
        var factory = ServiceLocator.GetService<ITenantDataAccessFactory>();
        return factory.CreateConnection(TenantId);
    }

    protected void LogAuditEvent(string action, object details)
    {
        var auditLogger = ServiceLocator.GetService<IAuditLogger>();
        auditLogger.Log(new AuditEvent
        {
            TenantId = TenantId,
            Action = action,
            Details = details,
            Timestamp = DateTime.UtcNow
        });
    }
}
```

