#### Example 3: Background Job Context Propagation (C#)

```csharp
// Background job with tenant context propagation
public class TenantBackgroundJob
{
    public async Task ProcessTenantReportAsync(string tenantId, Guid reportId)
    {
        // Restore tenant context in background job
        var tenantService = ServiceLocator.GetService<ITenantIdentifierService>();
        var tenantInfo = await tenantService.GetTenantAsync(tenantId);

        using (TenantContext.BeginScope(tenantInfo))
        {
            // All operations within scope automatically have tenant context
            var reportService = ServiceLocator.GetService<IReportService>();
            await reportService.GenerateReportAsync(reportId);

            // Database queries automatically filtered by tenant
            // Audit logs automatically tagged with tenant
            // Cache keys automatically namespaced with tenant
        }
    }
}

// Hangfire job scheduling with tenant context
public class TenantJobScheduler
{
    public void ScheduleTenantJob(Action<string> jobAction)
    {
        var tenantId = TenantContext.Current.TenantId;

        // Pass tenant ID to background job
        BackgroundJob.Enqueue(() => jobAction(tenantId));
    }
}
```

