#### Example 4: Event Handler Context Propagation (C#)

```csharp
// Event handler extracting tenant context from message
public class TenantEventHandler : IEventHandler<CustomerCreatedEvent>
{
    private readonly ITenantIdentifierService _tenantService;

    public async Task HandleAsync(CustomerCreatedEvent evt)
    {
        // Extract tenant ID from event metadata
        var tenantId = evt.Metadata["TenantId"];
        var tenantInfo = await _tenantService.GetTenantAsync(tenantId);

        using (TenantContext.BeginScope(tenantInfo))
        {
            // Process event within tenant context
            var customerService = ServiceLocator.GetService<ICustomerService>();
            await customerService.SendWelcomeEmailAsync(evt.CustomerId);
        }
    }
}

// Publishing events with tenant context
public class TenantEventPublisher
{
    public async Task PublishAsync<T>(T eventData) where T : class
    {
        var tenantId = TenantContext.Current.TenantId;

        var envelope = new EventEnvelope<T>
        {
            Data = eventData,
            Metadata = new Dictionary<string, string>
            {
                ["TenantId"] = tenantId,
                ["Timestamp"] = DateTime.UtcNow.ToString("O"),
                ["CorrelationId"] = Activity.Current?.Id
            }
        };

        await _eventBus.PublishAsync(envelope);
    }
}
