#### Example 6: Message Queue Consumer Context Propagation (Node.js)

```javascript
// Message queue consumer with tenant context propagation
const { AsyncLocalStorage } = require('async_hooks');
const tenantContext = new AsyncLocalStorage();

class TenantMessageConsumer {
    async consumeMessage(message) {
        // Extract tenant ID from message headers
        const tenantId = message.properties.headers['x-tenant-id'];

        if (!tenantId) {
            throw new Error('Missing tenant ID in message headers');
        }

        // Load tenant information
        const tenantService = getTenantService();
        const tenant = await tenantService.getTenant(tenantId);

        // Run message handler within tenant context
        return tenantContext.run(tenant, async () => {
            // All async operations maintain tenant context
            await this.processMessage(message);

            // Database queries automatically scoped
            // Logging automatically tagged with tenant
            // Distributed tracing includes tenant span tags
        });
    }

    async processMessage(message) {
        // Access tenant context anywhere in call stack
        const tenant = tenantContext.getStore();
        console.log(`Processing message for tenant: ${tenant.tenantId}`);

        // Business logic with automatic tenant isolation
        await customerService.updateCustomer(message.data);
    }
}

// Publishing messages with tenant context
function publishMessage(queueName, data) {
    const tenant = tenantContext.getStore();

    if (!tenant) {
        throw new Error('No tenant context available');
    }

    const message = {
        data: data,
        properties: {
            headers: {
                'x-tenant-id': tenant.tenantId,
                'x-correlation-id': getCurrentCorrelationId(),
                'x-timestamp': new Date().toISOString()
            }
        }
    };

    return messageQueue.publish(queueName, message);
}
